function [s, on] = ctl_capture(st, cp, hdev)
%CTL_CAPTURE  The large-error capture of the fine states: beyond capture_deg, an eigenaxis rate command sized
%   to the devices' torque and momentum authority, tracked by a rate loop (slews keep their profile).
%   Returns whether it ran.
%   vectors: 64
%   st: CtlState (passed rec)
%   cp: CtlParams (passed rec)
%   hdev: real[1][3] (passed a plain number)
%   returns s: CtlState (passed rec)
%   returns on: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = asils.alg.steplaws.CtlState_zero();
    on = false;
    s = st;
    on = false;
    if (~((s.mode == 4) || (cp.capture_deg <= 0)))
        qe = asils.alg.math.qerr(s.q_ref, s.q);
        th = (2 * asils.pc.acos_(asils.pc.choose_lazy((qe(4) > 1), @() 1, @() qe(4))));
        if (~(th < (cp.capture_deg * (pi / 180))))
            on = true;
            n = asils.pc.sqrt_((((qe(1) * qe(1)) + (qe(2) * qe(2))) + (qe(3) * qe(3))));
            if (n < 1e-12)
                n = 1e-12;
            end
            e = [(qe(1) * (1 / n)); (qe(2) * (1 / n)); (qe(3) * (1 / n))];
            jm = cp.j(1, 1);
            if (cp.j(2, 2) > jm)
                jm = cp.j(2, 2);
            end
            if (cp.j(3, 3) > jm)
                jm = cp.j(3, 3);
            end
            mincap = s.cap(1);
            minh = s.hcap(1);
            for i = (1):((3) - 1)
                if (s.cap((i) + 1) < mincap)
                    mincap = s.cap((i) + 1);
                end
                if (s.hcap((i) + 1) < minh)
                    minh = s.hcap((i) + 1);
                end
            end
            alpha = ((0.5 * mincap) / jm);
            wmax = (cp.capture_rate_deg_s * (pi / 180));
            if (((0.5 * minh) / jm) < wmax)
                wmax = ((0.5 * minh) / jm);
            end
            wref = asils.pc.mv(asils.alg.math.dcm(qe), s.w_ref);
            sp = asils.pc.sqrt_(((2 * alpha) * th));
            if (wmax < sp)
                sp = wmax;
            end
            wc = zeros(3, 1);
            for i = (0):((3) - 1)
                wc((i) + 1) = (wref((i) + 1) - (e((i) + 1) * sp));
            end
            kr = ((4 * alpha) / asils.pc.choose((wmax > 0.000001), wmax, 0.000001));
            if (kr > 0.5)
                kr = 0.5;
            end
            gy = asils.pc.cross_(s.w_est, ([cp.j(1, 1)*s.w_est(1) + cp.j(1, 2)*s.w_est(2) + cp.j(1, 3)*s.w_est(3); cp.j(2, 1)*s.w_est(1) + cp.j(2, 2)*s.w_est(2) + cp.j(2, 3)*s.w_est(3); cp.j(3, 1)*s.w_est(1) + cp.j(3, 2)*s.w_est(2) + cp.j(3, 3)*s.w_est(3)] + hdev));
            x = zeros(3, 1);
            for i = (0):((3) - 1)
                x((i) + 1) = (kr * (wc((i) + 1) - s.w_est((i) + 1)));
            end
            s.tau_req = ([cp.j(1, 1)*x(1) + cp.j(1, 2)*x(2) + cp.j(1, 3)*x(3); cp.j(2, 1)*x(1) + cp.j(2, 2)*x(2) + cp.j(2, 3)*x(3); cp.j(3, 1)*x(1) + cp.j(3, 2)*x(2) + cp.j(3, 3)*x(3)] + gy);
        end
    end
end
